using System.Reflection;
using System.Text.Json;
using CardGame.Core;
var method=typeof(CardResponseCompletionCostChecks).GetMethod("VerifyCommittedSlashPaymentDyingReturn",BindingFlags.NonPublic|BindingFlags.Static)!;
try { method.Invoke(null,null); Console.WriteLine(JsonSerializer.Serialize(new { expectedRed=false, reason="The regression unexpectedly passed on baseline Core." })); return 2; }
catch(TargetInvocationException e) {
 var error=e.InnerException!;
 var expected=error is InvalidOperationException && error.Message=="The final invariant rejects an invalid paid Slash invoice, frozen candidate, paused LoseHp or owned Dying return.";
 Console.WriteLine(JsonSerializer.Serialize(new { expectedRed=expected, coreRulesVersion=GameCheckpoint.CurrentRulesVersion, coreHasNewProjection=typeof(GameEngine).GetMethod("ProjectTypedCommittedSlashPaymentCursor",BindingFlags.NonPublic|BindingFlags.Instance) is not null, exception=error.ToString() }));
 return expected ? 0 : 3;
}
